function backAtStart(moves: string): boolean {
  let x = 0, y = 0;
  for (const m of moves) {
    if (m === "N") y++;
    else if (m === "S") y--;
    else if (m === "E") x++;
    else x--;
  }
  return x === 0 && y === 0;
}

