class Solution:
    def backAtStart(self, moves: str) -> bool:
        x = y = 0
        for m in moves:
            if m == "N":
                y += 1
            elif m == "S":
                y -= 1
            elif m == "E":
                x += 1
            else:
                x -= 1
        return x == 0 and y == 0

